  let destroyed = false;
  const gallery = versions !== 'menu';
  const presetProps = () => ({ panelId: id, presets: DialStore.getPresets(id), activePresetId: DialStore.getActivePresetId(id) });
  const presets = gallery ? null : mountPresetManager(host, presetProps());
